import{_ as t,o,c as a,a0 as r}from"./chunks/framework.CIWPqrYr.js";const h=JSON.parse('{"title":"6. Daily Standups & Asynchronous Reports","description":"","frontmatter":{},"headers":[],"relativePath":"08-daily-standups.md","filePath":"08-daily-standups.md"}'),i={name:"08-daily-standups.md"};function n(s,e,l,c,d,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_6-daily-standups-asynchronous-reports" tabindex="-1">6. Daily Standups &amp; Asynchronous Reports <a class="header-anchor" href="#_6-daily-standups-asynchronous-reports" aria-label="Permalink to &quot;6. Daily Standups &amp; Asynchronous Reports&quot;">​</a></h1><p>Stratos Daily Standups provides an asynchronous daily check-in module to keep engineering and product teams aligned without synchronous meeting overhead.</p><h2 id="enabling-daily-standups-for-a-project" tabindex="-1">Enabling Daily Standups for a Project <a class="header-anchor" href="#enabling-daily-standups-for-a-project" aria-label="Permalink to &quot;Enabling Daily Standups for a Project&quot;">​</a></h2><p>Daily Standups are <strong>opt-in per project</strong>.</p><ol><li>Open your project and click <strong>Project Settings</strong>.</li><li>Locate the <strong>Daily Standups</strong> configuration card.</li><li>Toggle <strong>Enable Daily Standups</strong> to ON.</li><li>Once enabled, a <strong>Daily Standup</strong> menu link appears at the bottom of the project&#39;s sidebar navigation (below board links).</li></ol><blockquote><p><strong>Data Safety Guarantee</strong>: Disabling Daily Standups hides check-in prompts and navigation, but <strong>never deletes historical check-in records</strong>. Re-enabling the feature at any time instantly restores all previous standup history.</p></blockquote><hr><h2 id="daily-check-in-process" tabindex="-1">Daily Check-in Process <a class="header-anchor" href="#daily-check-in-process" aria-label="Permalink to &quot;Daily Check-in Process&quot;">​</a></h2><p>Team members can log their daily intents in the morning and report outcomes in the evening.</p><ol><li>Navigate to <strong>Projects -&gt; [Your Project] -&gt; Daily Standup</strong>.</li><li>Click <strong>Log Today&#39;s Standup</strong> (or click today&#39;s cell in the Team Grid Matrix).</li><li><strong>Morning Focus &amp; Intent</strong>: <ul><li>Write your planned accomplishments for the day.</li><li><strong>Task Suggestions</strong>: Click any of the pre-populated task chips under <em>&quot;In-Progress Tasks&quot;</em> to insert Markdown links directly into your report (e.g. <code>[Fix API Auth](/boards/b1?task=t1)</code>).</li></ul></li><li><strong>Evening Accomplishments &amp; Outcome</strong>: <ul><li>Record what you completed.</li><li>Click pre-populated chips under <em>&quot;Completed Tasks&quot;</em> to automatically attach reference links.</li></ul></li><li><strong>Blockers &amp; Dependencies</strong>: <ul><li>Flag any blockers, dependencies, or impediments requiring lead or PM intervention.</li></ul></li><li>Click <strong>Save Standup Check-in</strong>.</li></ol><hr><h2 id="retroactive-past-date-check-ins" tabindex="-1">Retroactive Past-Date Check-ins <a class="header-anchor" href="#retroactive-past-date-check-ins" aria-label="Permalink to &quot;Retroactive Past-Date Check-ins&quot;">​</a></h2><p>If you missed logging a check-in yesterday or were out sick 3 days ago, you can retroactively log or update past entries.</p><ol><li>Open the <strong>Daily Standup</strong> page for your project.</li><li>In the <strong>Team Member Grid Matrix</strong>, find your row (indicated by the <strong>&quot;You&quot;</strong> badge).</li><li>Click on <strong>any past-date cell</strong> on your row.</li><li>The Check-in Modal will open pre-populated for that specific past date, allowing you to enter or revise your report.</li></ol><hr><h2 id="date-range-navigation-controls" tabindex="-1">Date Range Navigation &amp; Controls <a class="header-anchor" href="#date-range-navigation-controls" aria-label="Permalink to &quot;Date Range Navigation &amp; Controls&quot;">​</a></h2><p>The top control bar provides flexible date window options for team leads and project managers:</p><ul><li><strong>Date Presets</strong>: <ul><li><code>This Week (Mon–Fri)</code>: Shows the current work week.</li><li><code>This Month</code>: Shows the complete current calendar month.</li><li><code>Last Month</code>: Shows the previous full calendar month.</li><li><code>Last 30 Days</code>: Shows a rolling 30-day window.</li><li><code>Custom Date Range</code>: Pick custom Start and End dates.</li></ul></li><li><strong>Contextual Chevron Navigation (<code>←</code> / <code>→</code>)</strong>: <ul><li>Hover over chevrons to see dynamic tooltips (e.g., <em>&quot;Previous Month&quot;</em>, <em>&quot;Next Week&quot;</em>).</li><li>Clicking <code>←</code> or <code>→</code> shifts the view backward or forward while <strong>preserving your active preset selection</strong>.</li></ul></li></ul><hr><h2 id="team-lead-analytics-exporting-reports" tabindex="-1">Team Lead Analytics &amp; Exporting Reports <a class="header-anchor" href="#team-lead-analytics-exporting-reports" aria-label="Permalink to &quot;Team Lead Analytics &amp; Exporting Reports&quot;">​</a></h2><h3 id="executive-analytics-summary" tabindex="-1">Executive Analytics Summary <a class="header-anchor" href="#executive-analytics-summary" aria-label="Permalink to &quot;Executive Analytics Summary&quot;">​</a></h3><p>Project leads and managers can view high-level metrics for the selected date window:</p><ul><li><strong>Completion Rate %</strong>: Ratio of submitted standups versus expected weekday entries across team members.</li><li><strong>Total Standups Submitted</strong>: Count of completed or checked-in reports.</li><li><strong>Blockers Flagged</strong>: Count of reported blockers requiring assistance.</li></ul><h3 id="native-excel-xlsx-workbook-export" tabindex="-1">Native Excel (.xlsx) Workbook Export <a class="header-anchor" href="#native-excel-xlsx-workbook-export" aria-label="Permalink to &quot;Native Excel (.xlsx) Workbook Export&quot;">​</a></h3><ol><li>Click the <strong>Export Excel</strong> button in the header bar.</li><li>Stratos generates a native <code>.xlsx</code> workbook containing two sheets: <ul><li><strong>Sheet 1 (Executive Summary)</strong>: High-level metrics, date range, and team roster.</li><li><strong>Sheet 2 (Detailed Check-in Logs)</strong>: Complete log rows with timestamps, morning focus, evening outcomes, and blockers.</li></ul></li></ol><h3 id="printable-pdf-report-mode" tabindex="-1">Printable PDF Report Mode <a class="header-anchor" href="#printable-pdf-report-mode" aria-label="Permalink to &quot;Printable PDF Report Mode&quot;">​</a></h3><ol><li>Click the <strong>Print / PDF</strong> button in the header bar (or press <code>Ctrl+P</code> / <code>Cmd+P</code>).</li><li>Stratos applies clean print formatting, hiding sidebars and controls, allowing you to save a high-density PDF report directly from your browser.</li></ol>',27)])])}const g=t(i,[["render",n]]);export{h as __pageData,g as default};
